import type {
  MedusaRequest,
  MedusaResponse,
} from "@medusajs/framework/http"
import { createRbacPoliciesWorkflow } from "@medusajs/medusa/core-flows"

export async function POST(
  req: MedusaRequest,
  res: MedusaResponse
) {
  const { result } = await createRbacPoliciesWorkflow(req.scope)
    .run({
      input: {
        "policies": [{
          "key": "{value}",
          "resource": "{value}",
          "operation": "{value}"
        }]
      }
    })

  res.send(result)
}

